widget.solution:
#include <algorithm>
#include <cmath>
#include <vector>

double american_put(double s, double k, double r, double sigma, double t, int n) {
    if (t == 0.0) return std::max(k - s, 0.0);
    double dt = t / n;
    double u = std::exp(sigma * std::sqrt(dt)), d = 1.0 / u;
    double growth = std::exp(r * dt);
    double q = (growth - d) / (u - d), disc = 1.0 / growth;
    std::vector<double> v(n + 1);
    for (int j = 0; j <= n; ++j)
        v[j] = std::max(k - s * std::pow(u, j) * std::pow(d, n - j), 0.0);
    for (int i = n - 1; i >= 0; --i)
        for (int j = 0; j <= i; ++j) {
            double hold = disc * (q * v[j + 1] + (1 - q) * v[j]);
            double exercise = k - s * std::pow(u, j) * std::pow(d, i - j);
            v[j] = std::max(hold, exercise);
        }
    return v[0];
}

